ValidationRule.errorConditionFormula:
AND( ISPICKVAL(Region_Flag__c, "Jordan"),
IF(INCLUDES(Other_Sources_of_Fund__c, "Salary"),1,0) + IF(INCLUDES(Other_Sources_of_Fund__c, "Inheritance"),1,0) + IF(INCLUDES(Other_Sources_of_Fund__c, "Business Ownership"),1,0) + IF(INCLUDES(Other_Sources_of_Fund__c, "Investment"),1,0) + IF(INCLUDES(Other_Sources_of_Fund__c, "Family Support"),1,0) + IF(INCLUDES(Other_Sources_of_Fund__c, "Other"),1,0) > 3
)
